mapper.insert:
INSERT INTO llm_conversation_session (
    session_type, title, status, context_summary, model, token_count_total, metadata_json
) VALUES (
    #{sessionType}, #{title}, #{status}, #{contextSummary}, #{model}, #{tokenCountTotal}, #{metadataJson}
)

INSERT INTO llm_conversation_message (
    session_id, role, content, token_count, is_compressed, metadata_json
) VALUES (
    #{sessionId}, #{role}, #{content}, #{tokenCount}, #{isCompressed}, #{metadataJson}
)

mapper.select:
SELECT * FROM llm_conversation_message
WHERE session_id = #{sessionId}
ORDER BY id ASC

SELECT * FROM llm_conversation_message
WHERE session_id = #{sessionId}
  AND is_compressed = 0
ORDER BY id ASC
LIMIT #{limit}

mapper.update:
UPDATE llm_conversation_message
SET is_compressed = 1
WHERE session_id = #{sessionId}
  AND id <= #{beforeMessageId}
  AND is_compressed = 0

UPDATE llm_conversation_session
SET status = #{status}, update_time = NOW()
WHERE id = #{id}

UPDATE llm_conversation_session
SET token_count_total = #{tokenCountTotal}, update_time = NOW()
WHERE id = #{id}
